/* WellStream Platform — Custom Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

:root {
  --navy-900: #0D1B2A;
  --navy-800: #132238;
  --navy-700: #1B2838;
  --navy-600: #1E3048;
  --navy-500: #253D5B;
  --blue-500: #0077B6;
  --blue-400: #0096D6;
  --blue-300: #00B4D8;
  --blue-200: #48CAE4;
  --green-500: #6CC24A;
  --green-400: #7ED957;
  --gray-700: #3C424B;
  --gray-600: #4A5568;
  --gray-400: #8B9BB4;
  --gray-200: #C5D0DE;
  --gray-100: #E0E7EF;
  --white: #F8FAFC;
  --border: #2A3F5F;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--navy-900);
  color: var(--gray-100);
  line-height: 1.6;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }

/* ── Navigation ───────────────────────────────────────── */
.nav-wrapper {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  transition: background 0.3s;
}

.nav-inner {
  max-width: 1280px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px; height: 72px;
}

.nav-logo {
  font-size: 1.5rem; font-weight: 800; letter-spacing: -0.02em;
  color: var(--white);
}
.nav-logo span { color: var(--blue-300); }

.nav-links {
  display: flex; align-items: center; gap: 32px; list-style: none;
}
.nav-links > li { position: relative; }
.nav-links a, .nav-link-btn {
  color: var(--gray-200); font-size: 0.9rem; font-weight: 500;
  transition: color 0.2s; cursor: pointer; background: none; border: none;
  font-family: inherit; padding: 8px 0;
}
.nav-links a:hover, .nav-link-btn:hover { color: var(--blue-300); }

/* Platform dropdown */
.dropdown { position: relative; }
.dropdown-menu {
  position: absolute; top: calc(100% + 8px); left: -12px;
  min-width: 220px; background: var(--navy-700);
  border: 1px solid var(--border); border-radius: 8px;
  padding: 8px 0; opacity: 0; visibility: hidden;
  transform: translateY(-4px);
  transition: all 0.2s ease;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.dropdown:hover .dropdown-menu,
.dropdown.active .dropdown-menu {
  opacity: 1; visibility: visible; transform: translateY(0);
}
.dropdown-menu a {
  display: block; padding: 10px 20px; font-size: 0.875rem;
  transition: background 0.15s, color 0.15s;
}
.dropdown-menu a:hover {
  background: var(--navy-600); color: var(--blue-300);
}

/* CTA Button */
.btn-cta {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 10px 24px; border-radius: 6px; font-weight: 600;
  font-size: 0.875rem; transition: all 0.2s; cursor: pointer;
  border: none; font-family: inherit; text-decoration: none;
}
.btn-cta-primary {
  background: var(--blue-500); color: #fff;
}
.btn-cta-primary:hover {
  background: var(--blue-400); transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0,119,182,0.4);
}
.btn-cta-outline {
  background: transparent; color: var(--blue-300);
  border: 1.5px solid var(--blue-300);
}
.btn-cta-outline:hover {
  background: rgba(0,180,216,0.1);
}
.btn-cta-green {
  background: var(--green-500); color: #fff;
}
.btn-cta-green:hover {
  background: var(--green-400); transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(108,194,74,0.4);
}

/* Mobile nav */
.nav-mobile-toggle {
  display: none; background: none; border: none; cursor: pointer;
  width: 32px; height: 32px; position: relative;
}
.nav-mobile-toggle span {
  display: block; width: 24px; height: 2px; background: var(--gray-100);
  position: absolute; left: 4px; transition: all 0.3s;
}
.nav-mobile-toggle span:nth-child(1) { top: 8px; }
.nav-mobile-toggle span:nth-child(2) { top: 15px; }
.nav-mobile-toggle span:nth-child(3) { top: 22px; }

/* ── Hero Sections ────────────────────────────────────── */
.hero {
  padding: 140px 24px 80px; text-align: center;
  background: linear-gradient(160deg, var(--navy-900) 0%, var(--navy-700) 50%, var(--navy-800) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: -50%; right: -20%;
  width: 600px; height: 600px; border-radius: 50%;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-label {
  display: inline-block; font-size: 0.75rem; font-weight: 700;
  letter-spacing: 0.15em; text-transform: uppercase;
  color: var(--blue-300); margin-bottom: 16px;
  padding: 6px 16px; border: 1px solid rgba(0,180,216,0.3);
  border-radius: 4px; background: rgba(0,180,216,0.08);
}
.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem); font-weight: 800;
  line-height: 1.1; letter-spacing: -0.02em;
  max-width: 800px; margin: 0 auto 20px;
}
.hero-title .accent { color: var(--blue-300); }
.hero-subtitle {
  font-size: 1.125rem; color: var(--gray-400);
  max-width: 600px; margin: 0 auto 36px; line-height: 1.7;
}
.hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ── Section Layout ───────────────────────────────────── */
.section {
  padding: 80px 24px;
}
.section-dark { background: var(--navy-800); }
.section-navy { background: var(--navy-700); }
.section-inner {
  max-width: 1200px; margin: 0 auto;
}
.section-label {
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.15em;
  text-transform: uppercase; color: var(--blue-300); margin-bottom: 12px;
}
.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 700;
  line-height: 1.2; margin-bottom: 16px; letter-spacing: -0.01em;
}
.section-desc {
  font-size: 1.05rem; color: var(--gray-400); max-width: 640px;
  line-height: 1.7;
}
.section-desc.center { margin: 0 auto; }

/* ── Use Case Cards ───────────────────────────────────── */
.use-case-grid {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 24px; margin-top: 40px;
}
.use-case-card {
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 10px; padding: 28px; cursor: pointer;
  transition: all 0.25s; position: relative; overflow: hidden;
}
.use-case-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0;
  height: 3px; background: var(--blue-300); transform: scaleX(0);
  transform-origin: left; transition: transform 0.3s;
}
.use-case-card:hover {
  border-color: var(--blue-500); transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}
.use-case-card:hover::before { transform: scaleX(1); }
.use-case-icon {
  width: 44px; height: 44px; border-radius: 8px;
  background: rgba(0,180,216,0.12); display: flex;
  align-items: center; justify-content: center;
  margin-bottom: 16px; font-size: 1.25rem;
}
.use-case-card h3 {
  font-size: 1.05rem; font-weight: 600; margin-bottom: 8px;
}
.use-case-card p {
  font-size: 0.875rem; color: var(--gray-400); line-height: 1.6;
}

/* ── Tabs ──────────────────────────────────────────────── */
.tabs-wrapper { margin-top: 32px; }
.tab-list {
  display: flex; gap: 4px; border-bottom: 1px solid var(--border);
  margin-bottom: 32px; overflow-x: auto;
}
.tab-btn {
  padding: 12px 24px; font-size: 0.875rem; font-weight: 600;
  color: var(--gray-400); background: none; border: none;
  cursor: pointer; position: relative; white-space: nowrap;
  font-family: inherit; transition: color 0.2s;
}
.tab-btn:hover { color: var(--gray-200); }
.tab-btn.active { color: var(--blue-300); }
.tab-btn.active::after {
  content: ''; position: absolute; bottom: -1px; left: 0; right: 0;
  height: 2px; background: var(--blue-300); border-radius: 2px 2px 0 0;
}
.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Platform Ecosystem Diagram ───────────────────────── */
.ecosystem-diagram {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 32px; margin-top: 48px; position: relative;
}
.ecosystem-pillar {
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 12px; padding: 36px 28px; text-align: center;
  position: relative; transition: all 0.3s;
}
.ecosystem-pillar:hover {
  border-color: var(--blue-500);
  box-shadow: 0 0 40px rgba(0,180,216,0.1);
}
.ecosystem-icon {
  width: 64px; height: 64px; border-radius: 50%;
  background: rgba(0,180,216,0.1); border: 2px solid var(--blue-300);
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 20px; font-size: 1.5rem;
}
.ecosystem-pillar h3 {
  font-size: 1.1rem; font-weight: 700; margin-bottom: 12px;
  color: var(--blue-300);
}
.ecosystem-pillar p {
  font-size: 0.875rem; color: var(--gray-400); line-height: 1.6;
}
.ecosystem-connector {
  position: absolute; top: 50%; width: 32px; height: 2px;
  background: linear-gradient(90deg, var(--blue-500), var(--blue-300));
}

/* ── Circular Stats ───────────────────────────────────── */
.stats-row {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 40px; margin-top: 48px;
}
.stat-item { text-align: center; }
.stat-circle {
  width: 160px; height: 160px; border-radius: 50%;
  border: 4px solid var(--border); position: relative;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 20px; background: var(--navy-700);
}
.stat-circle svg {
  position: absolute; top: -4px; left: -4px;
  width: calc(100% + 8px); height: calc(100% + 8px);
  transform: rotate(-90deg);
}
.stat-circle svg circle {
  fill: none; stroke-width: 4; stroke-linecap: round;
  stroke: var(--blue-300);
  stroke-dasharray: var(--circumference);
  stroke-dashoffset: var(--offset);
  transition: stroke-dashoffset 1.5s ease;
}
.stat-value {
  font-size: 2.25rem; font-weight: 800; color: var(--blue-300);
  position: relative; z-index: 1;
}
.stat-value .unit { font-size: 1rem; font-weight: 600; }
.stat-label {
  font-size: 0.875rem; color: var(--gray-400); margin-top: 4px;
  max-width: 180px; margin-left: auto; margin-right: auto;
  line-height: 1.5;
}

/* ── Implementation Timeline ──────────────────────────── */
.timeline { margin-top: 48px; }
.timeline-item {
  display: flex; align-items: flex-start; gap: 24px;
  margin-bottom: 36px; position: relative;
}
.timeline-dot {
  width: 14px; height: 14px; border-radius: 50%;
  background: var(--blue-300); flex-shrink: 0; margin-top: 6px;
  box-shadow: 0 0 12px rgba(0,180,216,0.4);
}
.timeline-item:not(:last-child)::before {
  content: ''; position: absolute; left: 6px; top: 22px;
  width: 2px; height: calc(100% + 14px);
  background: var(--border);
}
.timeline-content { flex: 1; }
.timeline-duration {
  font-size: 1.5rem; font-weight: 800; color: var(--blue-300);
  margin-bottom: 4px;
}
.timeline-desc {
  font-size: 0.9rem; color: var(--gray-400); line-height: 1.6;
}
.timeline-bar {
  height: 6px; border-radius: 3px; background: var(--navy-600);
  margin-top: 12px; overflow: hidden;
}
.timeline-bar-fill {
  height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, var(--blue-500), var(--blue-300));
  transition: width 1.2s ease;
}

/* ── Accordion ────────────────────────────────────────── */
.accordion { margin-top: 40px; }
.accordion-item {
  border: 1px solid var(--border); border-radius: 8px;
  margin-bottom: 12px; overflow: hidden;
  background: var(--navy-700);
  transition: border-color 0.3s;
}
.accordion-item.open { border-color: var(--blue-500); }
.accordion-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 20px 24px; cursor: pointer; user-select: none;
  transition: background 0.2s;
}
.accordion-header:hover { background: var(--navy-600); }
.accordion-title {
  font-size: 1rem; font-weight: 600; display: flex;
  align-items: center; gap: 12px;
}
.accordion-title .icon { color: var(--blue-300); font-size: 1.1rem; }
.accordion-chevron {
  width: 24px; height: 24px; transition: transform 0.3s;
  color: var(--gray-400);
}
.accordion-item.open .accordion-chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.35s ease;
}
.accordion-body-inner {
  padding: 0 24px 20px; font-size: 0.9rem;
  color: var(--gray-400); line-height: 1.7;
}

/* ── Data Lifecycle Diagram ───────────────────────────── */
.lifecycle-diagram {
  display: flex; align-items: center; justify-content: center;
  gap: 16px; margin-top: 48px; flex-wrap: wrap;
}
.lifecycle-step {
  display: flex; flex-direction: column; align-items: center;
  gap: 12px; padding: 24px; background: var(--navy-700);
  border: 1px solid var(--border); border-radius: 10px;
  min-width: 140px; text-align: center; transition: all 0.3s;
}
.lifecycle-step:hover {
  border-color: var(--blue-500);
  box-shadow: 0 0 24px rgba(0,180,216,0.1);
}
.lifecycle-step .step-icon {
  width: 48px; height: 48px; border-radius: 50%;
  background: rgba(0,180,216,0.12); display: flex;
  align-items: center; justify-content: center;
  font-size: 1.2rem; color: var(--blue-300);
}
.lifecycle-step .step-label {
  font-size: 0.85rem; font-weight: 600; color: var(--gray-100);
}
.lifecycle-arrow {
  font-size: 1.5rem; color: var(--blue-500);
  animation: pulse-arrow 2s infinite;
}
@keyframes pulse-arrow {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

/* ── Testimonial Carousel ─────────────────────────────── */
.carousel { margin-top: 48px; position: relative; overflow: hidden; }
.carousel-track {
  display: flex; transition: transform 0.5s ease;
}
.carousel-card {
  min-width: 100%; padding: 0 12px;
}
.carousel-card-inner {
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 10px; padding: 36px; position: relative;
}
.carousel-card-inner::before {
  content: '\201C'; position: absolute; top: 16px; left: 24px;
  font-size: 4rem; color: rgba(0,180,216,0.15); font-family: Georgia, serif;
  line-height: 1;
}
.carousel-quote {
  font-size: 1.05rem; line-height: 1.7; color: var(--gray-200);
  font-style: italic; margin-bottom: 20px; position: relative; z-index: 1;
}
.carousel-author {
  font-size: 0.85rem; color: var(--blue-300); font-weight: 600;
}
.carousel-dots {
  display: flex; gap: 8px; justify-content: center; margin-top: 24px;
}
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--navy-500); border: none; cursor: pointer;
  transition: all 0.2s;
}
.carousel-dot.active { background: var(--blue-300); transform: scale(1.2); }

/* ── Security Features ────────────────────────────────── */
.security-list { margin-top: 32px; display: flex; flex-direction: column; gap: 20px; }
.security-item {
  display: flex; gap: 20px; padding: 24px;
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 10px; transition: all 0.25s;
}
.security-item:hover {
  border-color: var(--blue-500);
  box-shadow: 0 4px 20px rgba(0,0,0,0.2);
}
.security-icon {
  width: 48px; height: 48px; border-radius: 8px;
  background: rgba(0,180,216,0.1); display: flex;
  align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 1.25rem;
}
.security-item h3 {
  font-size: 1rem; font-weight: 600; margin-bottom: 6px;
}
.security-item p {
  font-size: 0.85rem; color: var(--gray-400); line-height: 1.6;
}

/* ── Integration Tabs Content ─────────────────────────── */
.integration-content {
  display: grid; grid-template-columns: 1fr 1fr; gap: 40px;
  align-items: center;
}
.integration-visual {
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 10px; padding: 32px; text-align: center;
  min-height: 280px; display: flex; align-items: center;
  justify-content: center;
}

/* ── ETL Benefits ─────────────────────────────────────── */
.etl-benefits {
  display: grid; grid-template-columns: repeat(2, 1fr);
  gap: 24px; margin-top: 40px;
}
.etl-benefit {
  display: flex; gap: 16px; padding: 24px;
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 8px; transition: all 0.25s;
}
.etl-benefit:hover { border-color: var(--green-500); }
.etl-check {
  width: 28px; height: 28px; border-radius: 50%;
  background: rgba(108,194,74,0.15); display: flex;
  align-items: center; justify-content: center;
  flex-shrink: 0; color: var(--green-500); font-size: 0.9rem;
  font-weight: 700;
}
.etl-benefit h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.etl-benefit p { font-size: 0.8rem; color: var(--gray-400); line-height: 1.5; }

/* ── Demo Form ────────────────────────────────────────── */
.demo-form-wrapper {
  max-width: 720px; margin: 0 auto;
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 12px; padding: 48px;
}
.form-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.form-group { display: flex; flex-direction: column; gap: 6px; }
.form-group.full { grid-column: 1 / -1; }
.form-label {
  font-size: 0.8rem; font-weight: 600; color: var(--gray-200);
  letter-spacing: 0.02em;
}
.form-label .required { color: var(--blue-300); }
.form-input, .form-select, .form-textarea {
  padding: 12px 16px; background: var(--navy-800);
  border: 1px solid var(--border); border-radius: 6px;
  color: var(--gray-100); font-size: 0.9rem;
  font-family: inherit; transition: border-color 0.2s;
  outline: none;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
  border-color: var(--blue-300);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.15);
}
.form-input.error, .form-select.error, .form-textarea.error {
  border-color: #ef4444;
}
.form-error {
  font-size: 0.75rem; color: #ef4444; display: none;
}
.form-error.visible { display: block; }
.form-textarea { resize: vertical; min-height: 100px; }
.form-submit {
  margin-top: 32px; width: 100%;
}

/* ── Support Contact ──────────────────────────────────── */
.support-grid {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 24px; margin-top: 40px;
}
.support-card {
  background: var(--navy-700); border: 1px solid var(--border);
  border-radius: 10px; padding: 28px; text-align: center;
  transition: all 0.25s;
}
.support-card:hover { border-color: var(--blue-500); }
.support-card .region {
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--blue-300); margin-bottom: 12px;
}
.support-card .name {
  font-size: 1rem; font-weight: 600; margin-bottom: 4px;
}
.support-card .email {
  font-size: 0.85rem; color: var(--gray-400);
}

/* ── Cookie Consent ───────────────────────────────────── */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 2000;
  background: var(--navy-700); border-top: 1px solid var(--border);
  padding: 20px 24px; display: flex; align-items: center;
  justify-content: space-between; gap: 24px;
  transform: translateY(100%); transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-text { font-size: 0.85rem; color: var(--gray-400); flex: 1; }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }
.cookie-btn {
  padding: 8px 20px; border-radius: 4px; font-size: 0.8rem;
  font-weight: 600; cursor: pointer; border: none;
  font-family: inherit; transition: all 0.2s;
}
.cookie-accept { background: var(--blue-500); color: #fff; }
.cookie-accept:hover { background: var(--blue-400); }
.cookie-decline { background: transparent; color: var(--gray-400); border: 1px solid var(--border); }
.cookie-decline:hover { border-color: var(--gray-400); }

/* ── Featured Product Banner ──────────────────────────── */
.featured-banner {
  background: linear-gradient(135deg, var(--navy-600), var(--blue-500));
  padding: 32px 24px; display: flex; align-items: center;
  justify-content: center; gap: 32px; flex-wrap: wrap;
  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
}
.featured-badge {
  font-size: 0.7rem; font-weight: 700; letter-spacing: 0.12em;
  text-transform: uppercase; background: rgba(255,255,255,0.15);
  padding: 4px 12px; border-radius: 3px;
}
.featured-product {
  font-size: 1.25rem; font-weight: 700;
}
.featured-tagline {
  font-size: 0.9rem; color: rgba(255,255,255,0.8);
}

